jsxGraph.script:
const optsFaceSide = { borders: { visible: false }, hasInnerBorders: false, fixed: true, fillColor: '#93c5fd', fillOpacity: 0.9 };
const optsFaceTop = { strokeColor: '#1e3a8a', strokeWidth: 2, fixed: true, fillColor: '#dbeafe', fillOpacity: 0.9, firstArrow: false, lastArrow: false };
const optsLine = { strokeColor: '#1e3a8a', strokeWidth: 2, firstArrow: false, lastArrow: false };
const optsLineDashed = { strokeColor: '#1e3a8a', strokeWidth: 1.5, dash: 2, firstArrow: false, lastArrow: false };
const optsDim = { strokeColor: '#e11d48', strokeWidth: 1.5, firstArrow: true, lastArrow: true };
const optsText = { strokeColor: '#e11d48', fontSize: 14, fontWeight: 'bold' };

const rx = 5;
const ry = 2;
const h = 12;
const steps = 60;

const topX = [], topY = [];
const botFrontX = [], botFrontY = [];
const botBackX = [], botBackY = [];
const botFullX = [], botFullY = [];

for(let i=0; i<=steps; i++) {
  const t = (i / steps) * 2 * Math.PI;
  topX.push(rx * Math.cos(t));
  topY.push(h/2 + ry * Math.sin(t));

  botFullX.push(rx * Math.cos(t));
  botFullY.push(-h/2 + ry * Math.sin(t));

  // Front half (PI to 2PI)
  if(t >= Math.PI) {
    botFrontX.push(rx * Math.cos(t));
    botFrontY.push(-h/2 + ry * Math.sin(t));
  }
  // Back half (0 to PI)
  if(t <= Math.PI) {
    botBackX.push(rx * Math.cos(t));
    botBackY.push(-h/2 + ry * Math.sin(t));
  }
}

board.create('polygon', [[-rx, h/2], [rx, h/2], [rx, -h/2], [-rx, -h/2]], optsFaceSide);
board.create('curve', [botFullX, botFullY], { strokeWidth: 0, fillColor: '#93c5fd', fillOpacity: 0.9, fixed: true, firstArrow: false, lastArrow: false });
board.create('curve', [topX, topY], optsFaceTop);

board.create('segment', [[-rx, h/2], [-rx, -h/2]], optsLine);
board.create('segment', [[rx, h/2], [rx, -h/2]], optsLine);

board.create('curve', [botFrontX, botFrontY], optsLine);
board.create('curve', [botBackX, botBackY], optsLineDashed);

board.create('point', [0, h/2], { size: 3, face: 'circle', color: '#1e3a8a', name: '', withLabel: false, fixed: true });
board.create('segment', [[0, h/2], [rx, h/2]], optsLineDashed);
board.create('text', [rx/2, h/2 + 0.2], '5 cm', { ...optsText, anchorX: 'middle', anchorY: 'bottom' });

board.create('segment', [[rx + 1.5, h/2], [rx + 1.5, -h/2]], { ...optsDim });
board.create('text', [rx + 1.8, 0], '12 cm', { ...optsText, anchorX: 'left', anchorY: 'middle' });
